fn solve(word: Vec<char>) -> Vec<char> {
    // Define the two fixed sets of letters
    const SET_A: [char; 15] = [
        'A', 'E', 'F', 'H', 'I', 'K', 'L', 'M', 'N', 'T', 'V', 'W', 'X', 'Y', 'Z',
    ];
    const SET_B: [char; 11] = [
        'B', 'C', 'D', 'G', 'J', 'O', 'P', 'Q', 'R', 'S', 'U',
    ];

    // Flags to check if all characters stay within one set
    let mut all_in_a = true;
    let mut all_in_b = true;

    for &ch in &word {
        if !SET_A.contains(&ch) {
            all_in_a = false;
        }
        if !SET_B.contains(&ch) {
            all_in_b = false;
        }
        // Early exit if neither set is still possible
        if !all_in_a && !all_in_b {
            break;
        }
    }

    if all_in_a || all_in_b {
        vec!['Y', 'E', 'S']
    } else {
        vec!['N', 'O']
    }
}

